//! Bindings to the bundled libaom (generated by build.rs).

#[allow(non_camel_case_types, non_upper_case_globals, non_snake_case, dead_code, unused, clippy::all)]
pub mod sys {
    include!(concat!(env!("OUT_DIR"), "/aom_bindings.rs"));
}

use std::ffi::CStr;

pub fn version() -> String {
    unsafe { CStr::from_ptr(sys::aom_codec_version_str()).to_string_lossy().into_owned() }
}

pub fn error_detail(ctx: *mut sys::aom_codec_ctx_t) -> String {
    unsafe {
        let msg = sys::aom_codec_error(ctx);
        let detail = sys::aom_codec_error_detail(ctx);
        let mut s = if msg.is_null() { String::from("unknown error") } else { CStr::from_ptr(msg).to_string_lossy().into_owned() };
        if !detail.is_null() {
            s.push_str(": ");
            s.push_str(&CStr::from_ptr(detail).to_string_lossy());
        }
        s
    }
}

/// YCbCr luma coefficients (Kr, Kb) for an AV1/H.273 matrix_coefficients value.
pub fn luma_coefficients(mc: u32) -> (f32, f32) {
    match mc {
        1 => (0.2126, 0.0722),        // BT.709
        9 | 10 => (0.2627, 0.0593),   // BT.2020
        4 => (0.30, 0.11),            // FCC
        7 => (0.212, 0.087),          // SMPTE 240M
        _ => (0.299, 0.114),          // BT.601 (5, 6) and unspecified
    }
}
